#!/bin/bash\n# Clean build artifacts\n\nset -e\n\nPROJECT_ROOT=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && cd .. && pwd)\"\nBUILD_DIR=\"${BUILD_DIR:-$PROJECT_ROOT/build}\"\nISO_DIR=\"$PROJECT_ROOT/iso\"\n\necho \"[INFO] Cleaning smg4OS build artifacts...\"\n\nread -p \"Are you sure? This will delete $BUILD_DIR and $ISO_DIR [y/N] \" -n 1 -r\necho\n\nif [[ $REPLY =~ ^[Yy]$ ]]; then\n    if [ -d \"$BUILD_DIR\" ]; then\n        echo \"[INFO] Removing build directory: $BUILD_DIR\"\n        rm -rf \"$BUILD_DIR\"\n    fi\n    \n    if [ -d \"$ISO_DIR\" ]; then\n        echo \"[INFO] Removing ISO directory: $ISO_DIR\"\n        rm -rf \"$ISO_DIR\"\n    fi\n    \n    echo \"[INFO] Clean complete\"\n    echo \"To rebuild: ./scripts/build-all.sh\"\nelse\n    echo \"[INFO] Clean cancelled\"\nfi\n"